            data: {
                labels: ['Equipos', 'Mano de Obra', 'Materiales', 'Transporte'],
                datasets: [{
                    data: [, , , ],
                    backgroundColor: ['#6d879d', '#7a9282', '#c58b6b', '#78aeb1'],
                    borderWidth: 0
                }]
