                cutout: '70%'
            }
        });
    }
});

section.script:

document.addEventListener('DOMContentLoaded', function () {
    var root = document.getElementById('geosis-calendar');
    if (!root) {
        return;
    }

    var items = [];
    try {
        items = JSON.parse(root.dataset.items || '[]');
    } catch (error) {
        items = [];
    }

    var viewportHeader = root.querySelector('.geosis-calendar__header .geosis-calendar__viewport');
    var viewportBody = root.querySelector('.geosis-calendar__body .geosis-calendar__viewport');
    var canvasHeader = root.querySelector('.geosis-calendar__header .geosis-calendar__canvas');
    var canvasBody = root.querySelector('.geosis-calendar__body .geosis-calendar__canvas');
    var monthsEl = root.querySelector('.geosis-calendar__months');
    var daysEl = root.querySelector('.geosis-calendar__days');
    var weekendsEl = root.querySelector('.geosis-calendar__weekends');
    var gridEl = root.querySelector('.geosis-calendar__grid');
    var lanesEl = root.querySelector('.geosis-calendar__lanes');
    var todayLine = root.querySelector('.geosis-calendar__today-line');
    var tabs = root.closest('.geosis-shot-panel').querySelectorAll('.geosis-shot-tab');

    function parseDate(value) {
        var parts = (value || '').split('-');
        return new Date(Date.UTC(parseInt(parts[0] || '0', 10), parseInt(parts[1] || '1', 10) - 1, parseInt(parts[2] || '1', 10)));
    }

    function addDays(date, amount) {
        var next = new Date(date.getTime());
        next.setUTCDate(next.getUTCDate() + amount);
        return next;
    }

    function addMonths(date, amount) {
        return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + amount, 1));
    }

    function addYears(date, amount) {
        return new Date(Date.UTC(date.getUTCFullYear() + amount, 0, 1));
    }

    function diffDays(a, b) {
        return Math.round((b - a) / 86400000);
    }

    function sameMonth(a, b) {
        return a.getUTCFullYear() === b.getUTCFullYear() && a.getUTCMonth() === b.getUTCMonth();
    }

    function sameYear(a, b) {
        return a.getUTCFullYear() === b.getUTCFullYear();
    }

    function startOfWeek(date) {
        var day = date.getUTCDay() || 7;
        return addDays(date, 1 - day);
    }

    function startOfMonth(date) {
        return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), 1));
    }

    function startOfYear(date) {
        return new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
    }

    function monthLabel(date) {
        return date.toLocaleDateString('es-EC', { month: 'long', year: 'numeric', timeZone: 'UTC' });
    }

    function shortMonthLabel(date) {
        return date.toLocaleDateString('es-EC', { month: 'short', timeZone: 'UTC' });
    }

    function dayLabel(date) {
        return date.toLocaleDateString('es-EC', { day: 'numeric', timeZone: 'UTC' });
    }

    function weekLabel(date) {
        var end = addDays(date, 6);
        return dayLabel(date) + ' - ' + dayLabel(end);
    }

    function buildUnits(scale, today, minDate, maxDate) {
        var units = [];
        var cursor;
        var end;

        if (scale === 'day') {
            cursor = addDays(minDate, -1);
            end = addDays(maxDate, 1);
            while (cursor <= end) {
                units.push(new Date(cursor.getTime()));
                cursor = addDays(cursor, 1);
            }
        } else if (scale === 'week') {
            cursor = startOfWeek(minDate < today ? minDate : today);
            end = startOfWeek(maxDate > today ? maxDate : today);
            while (cursor <= end) {
                units.push(new Date(cursor.getTime()));
                cursor = addDays(cursor, 7);
            }
        } else if (scale === 'month') {
            cursor = startOfMonth(minDate < today ? minDate : today);
            end = startOfMonth(maxDate > today ? maxDate : today);
            while (cursor <= end) {
                units.push(new Date(cursor.getTime()));
                cursor = addMonths(cursor, 1);
            }
        } else {
            cursor = startOfYear(minDate < today ? minDate : today);
            end = startOfYear(maxDate > today ? maxDate : today);
            while (cursor <= end) {
                units.push(new Date(cursor.getTime()));
                cursor = addYears(cursor, 1);
            }
        }

        return units;
    }

    function getCellWidth(scale) {
        return {
            day: 70,
            week: 128,
            month: 150,
            year: 190,
        }[scale] || 70;
    }

    function getUnitIndex(date, units, scale) {
        var i;
        if (scale === 'day') {
            return diffDays(units[0], date);
        }
        for (i = units.length - 1; i >= 0; i--) {
            if (date >= units[i]) {
                return i;
            }
        }
        return 0;
    }

    function buildLaneEntries(scale, units) {
        var prepared = items.map(function (item) {
            var start = parseDate(item.start);
            var end = parseDate(item.end);
            return {
                data: item,
                start: start,
                end: end,
                startIndex: getUnitIndex(start, units, scale),
                endIndex: getUnitIndex(end, units, scale),
            };
        }).sort(function (a, b) {
            if (a.startIndex === b.startIndex) {
                return a.endIndex - b.endIndex;
            }
            return a.startIndex - b.startIndex;
        });

        var lanes = [];
        prepared.forEach(function (entry) {
            var placed = false;
            lanes.forEach(function (lane) {
                if (!placed && entry.startIndex > lane.lastIndex) {
                    lane.items.push(entry);
                    lane.lastIndex = entry.endIndex;
                    placed = true;
                }
            });
            if (!placed) {
                lanes.push({
                    lastIndex: entry.endIndex,
                    items: [entry],
                });
            }
        });
        return lanes;
    }

    function clearCanvas() {
        monthsEl.innerHTML = '';
        daysEl.innerHTML = '';
        weekendsEl.innerHTML = '';
        gridEl.innerHTML = '';
        lanesEl.innerHTML = '';
    }

    function renderScale(scale, shouldFocusToday) {
        if (!items.length) {
            clearCanvas();
            return;
        }

        var today = parseDate(root.dataset.today);
        var startDates = items.map(function (item) { return parseDate(item.start); });
        var endDates = items.map(function (item) { return parseDate(item.end); });
        var minDate = startDates.reduce(function (acc, current) { return current < acc ? current : acc; }, today);
        var maxDate = endDates.reduce(function (acc, current) { return current > acc ? current : acc; }, today);
        var units = buildUnits(scale, today, minDate, maxDate);
        var cellWidth = getCellWidth(scale);
        var width = units.length * cellWidth;
        var labelFormatter;
        var groupFormatter;
        var sameGroupChecker;

        if (!units.length) {
            return;
        }

        clearCanvas();
        canvasHeader.style.width = width + 'px';
        canvasBody.style.width = width + 'px';

        if (scale === 'day') {
            labelFormatter = function (date) { return dayLabel(date); };
            groupFormatter = function (date) { return monthLabel(date); };
            sameGroupChecker = sameMonth;
        } else if (scale === 'week') {
            labelFormatter = function (date) { return weekLabel(date); };
            groupFormatter = function (date) { return monthLabel(date); };
            sameGroupChecker = sameMonth;
        } else if (scale === 'month') {
            labelFormatter = function (date) { return shortMonthLabel(date); };
            groupFormatter = function (date) { return String(date.getUTCFullYear()); };
            sameGroupChecker = sameYear;
        } else {
            labelFormatter = function (date) { return String(date.getUTCFullYear()); };
            groupFormatter = function () { return 'Periodo'; };
            sameGroupChecker = function () { return true; };
        }

        units.forEach(function (unit, index) {
            var left = index * cellWidth;
            var cell = document.createElement('span');
            cell.className = 'geosis-calendar__day';
            cell.style.left = left + 'px';
            cell.style.width = cellWidth + 'px';
            cell.textContent = labelFormatter(unit);
            daysEl.appendChild(cell);

            var line = document.createElement('span');
            line.className = 'geosis-calendar__grid-line';
            line.style.left = left + 'px';
            gridEl.appendChild(line);

            if (scale === 'day' && (unit.getUTCDay() === 0 || unit.getUTCDay() === 6)) {
                var weekend = document.createElement('span');
                weekend.className = 'geosis-calendar__weekend';
                weekend.style.left = left + 'px';
                weekend.style.width = cellWidth + 'px';
                weekendsEl.appendChild(weekend);
            }

            if (index === 0 || !sameGroupChecker(unit, units[index - 1])) {
                var endIndex = index;
                while (endIndex + 1 < units.length && sameGroupChecker(unit, units[endIndex + 1])) {
                    endIndex++;
                }
                var headerGroup = document.createElement('span');
                headerGroup.className = 'geosis-calendar__month';
                headerGroup.style.left = left + 'px';
                headerGroup.style.width = ((endIndex - index + 1) * cellWidth) + 'px';
                headerGroup.textContent = groupFormatter(unit);
                monthsEl.appendChild(headerGroup);
            }
        });

        var lanes = buildLaneEntries(scale, units);
        lanes.forEach(function (lane, laneIndex) {
            var laneRow = document.createElement('div');
            laneRow.className = 'geosis-calendar__lane';
            laneRow.style.top = (laneIndex * 32) + 'px';

            lane.items.forEach(function (entry) {
                var bar = document.createElement('div');
                bar.className = 'geosis-calendar__bar' + (entry.data.is_critical ? ' is-critical' : '');
                bar.style.left = (entry.startIndex * cellWidth) + 'px';
                bar.style.width = ((entry.endIndex - entry.startIndex + 1) * cellWidth) + 'px';
                bar.textContent = entry.data.content;
                laneRow.appendChild(bar);
            });

            lanesEl.appendChild(laneRow);
        });

        lanesEl.style.height = Math.max(lanes.length * 32, 96) + 'px';
        canvasBody.style.height = Math.max(lanes.length * 32, 96) + 'px';

        var todayIndex = getUnitIndex(today, units, scale);
        if (todayIndex >= 0 && todayIndex < units.length) {
            todayLine.style.left = (todayIndex * cellWidth) + 'px';
            todayLine.style.display = 'block';
        } else {
            todayLine.style.display = 'none';
        }

        if (shouldFocusToday) {
            var offset = Math.max((todayIndex * cellWidth) - 180, 0);
            viewportBody.scrollLeft = offset;
            viewportHeader.scrollLeft = offset;
        } else {
            viewportBody.scrollLeft = 0;
            viewportHeader.scrollLeft = 0;
        }
    }

    function activateTab(nextScale) {
        tabs.forEach(function (tab) {
            tab.classList.toggle('is-active', tab.dataset.scale === nextScale);
        });

        if (nextScale === 'today') {
            renderScale('day', true);
        } else {
            renderScale(nextScale, false);
        }
    }

    viewportBody.addEventListener('scroll', function () {
        viewportHeader.scrollLeft = viewportBody.scrollLeft;
    });

    tabs.forEach(function (tab) {
        tab.addEventListener('click', function () {
            activateTab(tab.dataset.scale);
        });
    });

    activateTab('today');
});

div.script:

document.addEventListener('DOMContentLoaded', function () {
    function portalJson(url, params) {
        return fetch(url, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-Requested-With': 'XMLHttpRequest'
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: params || {}
            })
        }).then(function (response) {
            return response.json();
        }).then(function (payload) {
            if (payload.error) {
                throw new Error(payload.error.data && payload.error.data.message ? payload.error.data.message : 'No se pudo completar la acción');
            }
            return payload.result || payload;
        });
    }

    function reloadPage() {
        window.location.reload();
    }

    document.querySelectorAll('.geosis-portal-priority-btn').forEach(function (button) {
        button.addEventListener('click', function () {
            portalJson('/my/task/' + button.dataset.taskId + '/toggle_priority', {}).then(reloadPage);
        });
    });

    document.querySelectorAll('.geosis-portal-state-option').forEach(function (button) {
        button.addEventListener('click', function () {
            portalJson('/my/task/' + button.dataset.taskId + '/update_state', {
                state_val: button.dataset.state
            }).then(reloadPage);
        });
    });

    document.querySelectorAll('.geosis-portal-assignee-option').forEach(function (button) {
        button.addEventListener('click', function () {
            portalJson('/my/task/' + button.dataset.taskId + '/update_assignee', {
                user_id: button.dataset.userId || false
            }).then(reloadPage);
        });
    });

    document.querySelectorAll('.geosis-portal-user-search').forEach(function (input) {
        input.addEventListener('input', function () {
            var text = (input.value || '').toLowerCase();
            var panel = input.closest('.geosis-portal-menu__panel');
            if (!panel) {
                return;
            }
            panel.querySelectorAll('.geosis-portal-assignee-option').forEach(function (option) {
                var label = (option.dataset.userName || option.textContent || '').toLowerCase();
                option.style.display = !text || label.indexOf(text) !== -1 ? '' : 'none';
            });
        });
    });

    document.querySelectorAll('.geosis-portal-stage-add').forEach(function (button) {
        button.addEventListener('click', function () {
            var column = button.closest('.geosis-portal-kanban__column');
            if (!column) {
                return;
            }
            column.classList.toggle('is-open');
            var input = column.querySelector('.geosis-portal-stage-input');
            if (input && column.classList.contains('is-open')) {
                input.focus();
            }
        });
    });

    document.querySelectorAll('.geosis-portal-stage-save').forEach(function (button) {
        button.addEventListener('click', function () {
            var column = button.closest('.geosis-portal-kanban__column');
            var trigger = column ? column.querySelector('.geosis-portal-stage-add') : null;
            var input = column ? column.querySelector('.geosis-portal-stage-input') : null;
            if (!trigger || !input || !input.value.trim()) {
                return;
            }
            portalJson('/my/project/' + trigger.dataset.projectId + '/add_stage', {
                name: input.value.trim()
            }).then(reloadPage);
        });
    });
});

t.script:
document.addEventListener('DOMContentLoaded', function() {
    function portalJson(url, params) {
        return fetch(url, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-Requested-With': 'XMLHttpRequest'
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: params || {}
            })
        }).then(function(response) {
            return response.json();
        }).then(function(payload) {
            if (payload.error) {
                throw new Error(payload.error.data && payload.error.data.message ? payload.error.data.message : 'No se pudo completar la accion');
            }
            return payload.result || payload;
        });
    }

    function showBoardMessage(message, isError) {
        var toast = document.getElementById('geosis-board-toast');
        if (!toast) {
            toast = document.createElement('div');
            toast.id = 'geosis-board-toast';
            toast.className = 'geosis-board-toast';
            document.body.appendChild(toast);
        }
        toast.textContent = message;
        toast.classList.toggle('is-error', !!isError);
        toast.classList.add('is-visible');
        window.clearTimeout(window.geosisBoardToastTimer);
        window.geosisBoardToastTimer = window.setTimeout(function() {
            toast.classList.remove('is-visible');
        }, 2200);
    }

    document.querySelectorAll('.geosis-shot-star').forEach(function(button) {
        button.addEventListener('click', function() {
            portalJson('/my/task/' + button.dataset.taskId + '/toggle_priority', {}).then(function(result) {
                if (!result.success) {
                    throw new Error(result.error || 'No se pudo actualizar la prioridad');
                }
                window.location.reload();
            }).catch(function(error) {
                showBoardMessage(error.message, true);
            });
        });
    });

    document.querySelectorAll('.geosis-task-assignee').forEach(function(select) {
        select.addEventListener('change', function() {
            portalJson('/my/task/' + select.dataset.taskId + '/update_assignee', {
                user_id: select.value || false
            }).then(function(result) {
                if (!result.success) {
                    throw new Error(result.error || 'No se pudo actualizar el responsable');
                }
                showBoardMessage('Responsable actualizado');
                window.location.reload();
            }).catch(function(error) {
                showBoardMessage(error.message, true);
            });
        });
    });

    document.querySelectorAll('.geosis-task-state').forEach(function(select) {
        select.addEventListener('change', function() {
            portalJson('/my/task/' + select.dataset.taskId + '/update_state', {
                state_val: select.value
            }).then(function(result) {
                if (!result.success) {
                    throw new Error(result.error || 'No se pudo actualizar el estado');
                }
                showBoardMessage('Estado actualizado');
            }).catch(function(error) {
                showBoardMessage(error.message, true);
            });
        });
    });

    document.querySelectorAll('.geosis-task-stage').forEach(function(select) {
        select.addEventListener('change', function() {
            portalJson('/my/task/' + select.dataset.taskId + '/update_stage', {
                stage_id: select.value || false
            }).then(function(result) {
                if (!result.success) {
                    throw new Error(result.error || 'No se pudo mover la tarea');
                }
                window.location.reload();
            }).catch(function(error) {
                showBoardMessage(error.message, true);
            });
        });
    });

    function bindDateChange(selector) {
        document.querySelectorAll(selector).forEach(function(input) {
            input.addEventListener('change', function() {
                var card = input.closest('.geosis-shot-task-card');
                var startInput = card.querySelector('.geosis-task-start');
                var endInput = card.querySelector('.geosis-task-end');
                portalJson('/my/task/' + input.dataset.taskId + '/update_dates', {
                    start_date: startInput.value || false,
                    end_date: endInput.value || false
                }).then(function(result) {
                    if (!result.success) {
                        throw new Error(result.error || 'No se pudieron actualizar las fechas');
                    }
                    showBoardMessage('Fechas actualizadas');
                    window.location.reload();
                }).catch(function(error) {
                    showBoardMessage(error.message, true);
                });
            });
        });
    }

    bindDateChange('.geosis-task-start');
    bindDateChange('.geosis-task-end');

    document.querySelectorAll('.geosis-create-stage-btn').forEach(function(button) {
        button.addEventListener('click', function() {
            var input = document.getElementById(button.dataset.inputId);
            var stageName = input.value.trim();
            if (!stageName) {
                showBoardMessage('Escribe un nombre para la etapa', true);
                input.focus();
                return;
            }
            portalJson('/my/project/' + button.dataset.projectId + '/add_stage', {
                name: stageName
            }).then(function(result) {
                if (!result.success) {
                    throw new Error(result.error || 'No se pudo crear la etapa');
                }
                window.location.reload();
            }).catch(function(error) {
                showBoardMessage(error.message, true);
            });
        });
    });
});

