document.addEventListener('DOMContentLoaded', function() {
    console.log("MAPA VERSION 6.0 - MURO DE ACERO ACTIVADO");
    var initialLat = -0.1807;
    var initialLng = -78.4678;

    // OPCIONES DE MAPA PARA EVITAR AUTO-CENTRO
    var mapOptions = {
        scrollWheelZoom: true,
        touchZoom: true,
        trackResize: false, // Evita que Odoo lo mueva al cambiar tamaño de ventana
        worldCopyJump: false
    };

    var map = L.map('project_map_picker', mapOptions).setView([initialLat, initialLng], 12);

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; OpenStreetMap'
    }).addTo(map);

    var marker = L.marker([initialLat, initialLng], {
        draggable: true
    }).addTo(map);

    setTimeout(function() {
        map.invalidateSize();
    }, 250);

    window.addEventListener('resize', function() {
        setTimeout(function() {
            map.invalidateSize();
        }, 100);
    });

    // Función protegida
    window.geosisMapLock = true; 

    function updateFields(lat, lng) {
        document.getElementById('project_lat').value = lat.toFixed(7);
        document.getElementById('project_lng').value = lng.toFixed(7);
    }

    marker.on('dragend', function(e) {
        var pos = marker.getLatLng();
        updateFields(pos.lat, pos.lng);
    });

    map.on('click', function(e) {
        marker.setLatLng(e.latlng);
        updateFields(e.latlng.lat, e.latlng.lng);
    });

    // Botón detectar (CON PROTECCION DE EVENTOS)
    document.getElementById('btn_detect_location').addEventListener('click', function(e) {
        e.preventDefault();
        e.stopImmediatePropagation(); // MATAR CUALQUIER OTRO SCRIPT
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(function(position) {
                var lat = position.coords.latitude;
                var lng = position.coords.longitude;
                map.setView([lat, lng], 17);
                marker.setLatLng([lat, lng]);
                updateFields(lat, lng);

                fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`)
                    .then(response => response.json())
                    .then(data => {
                        if (data.address) {
                            var city = data.address.city || data.address.town || data.address.village || data.address.county || '';
                            if (city) document.getElementById('project_location').value = city;
                        }
                    }).catch(e => {});
            }, null, { enableHighAccuracy: true });
        }
    });

    // Buscador (CON PROTECCION DE EVENTOS)
    document.getElementById('btn_search_map').addEventListener('click', function(e) {
        e.preventDefault();
        e.stopImmediatePropagation(); // MATAR CUALQUIER OTRO SCRIPT
        var query = document.getElementById('project_location').value;
        if (query) {
            fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}`)
                .then(response => response.json())
                .then(data => {
                    if (data.length > 0) {
                        var lat = parseFloat(data[0].lat);
                        var lon = parseFloat(data[0].lon);
                        map.setView([lat, lon], 14);
                        marker.setLatLng([lat, lon]);
                        updateFields(lat, lon);
                    }
                }).catch(e => {});
        }
    });

    // ESTO ES LO MAS IMPORTANTE: 
    // Si algo externo intenta mover el mapa, lo bloqueamos.
    var originalSetView = map.setView;
    map.setView = function(center, zoom, options) {
        if (arguments.length > 0 && !window.geosisMapLock) {
            console.log("Odoo intentó mover el mapa, pero lo bloqueamos.");
            return this;
        }
        window.geosisMapLock = false; // Permitir solo este movimiento
        return originalSetView.apply(this, arguments);
    };
});

