div.script:
function geosisSaveBudgetLine(el, isManual) {
     var tr = el.closest('tr');
     if (!tr) return;

     var lineId = tr.getAttribute('data-line-id');
     var budgetId = tr.getAttribute('data-budget-id');
     if (!lineId || !budgetId) return;

     var statusEl = tr.querySelector('.geosis-budget-line-status');
     function setStatus(msg, isError) {
         if (!statusEl) return;
         statusEl.textContent = msg || '';
         statusEl.className = 'small mt-1 geosis-budget-line-status ' + (isError ? 'text-danger' : 'text-success');
     }

     var startInput = tr.querySelector('input[name="date_start"]');
     var endInput = tr.querySelector('input[name="date_end"]');
     var startValue = startInput ? (startInput.value || '').trim() : '';
     var endValue = endInput ? (endInput.value || '').trim() : '';

     if (!isManual && (!startValue || !endValue)) {
         return;
     }

     var csrfEl = document.querySelector('input[name="csrf_token"]');
     var csrfToken = csrfEl ? csrfEl.value : (window.odoo && window.odoo.csrf_token) || '';

     var formData = new FormData();
     formData.append('csrf_token', csrfToken);
     formData.append('date_start', startValue);
     formData.append('date_end', endValue);

     var qtyInput = tr.querySelector('input[name="quantity"]');
     if (qtyInput) formData.append('quantity', qtyInput.value);

     var priceInput = tr.querySelector('input[name="unit_price"]');
     if (priceInput) formData.append('unit_price', priceInput.value);

     var chapterSelect = tr.querySelector('select[name="chapter_id"]');
     if (chapterSelect) formData.append('chapter_id', chapterSelect.value);

     var noteInput = tr.querySelector('input[name="note"]');
     if (noteInput) formData.append('note', noteInput.value);

     setStatus(isManual ? 'Guardando...' : 'Guardando fechas...', false);

     var actionUrl = '/my/budget/' + budgetId + '/line/' + lineId + '/update-ajax';

     fetch(actionUrl, {
         method: 'POST',
         body: formData,
         credentials: 'same-origin',
         headers: {
             'X-Requested-With': 'XMLHttpRequest'
         }
     })
     .then(function (response) {
         if (!response.ok) {
             throw new Error('Error al guardar');
         }
         return response.json();
     })
     .then(function (data) {
         if (!data || !data.ok) {
             throw new Error((data && data.message) || 'Error al guardar');
         }
         var durationCell = tr.querySelector('.geosis-line-duration');
         var subtotalCell = tr.querySelector('.geosis-line-subtotal');
         if (durationCell) durationCell.textContent = data.duration || 0;
         if (subtotalCell) subtotalCell.textContent = '$' + Number(data.subtotal || 0).toFixed(2);
         setStatus(isManual ? 'Cambios guardados.' : 'Fechas guardadas.', false);
         setTimeout(function() {
             setStatus('', false);
         }, 3000);
     })
     .catch(function (error) {
         setStatus(error.message || 'Error al guardar.', true);
     });
 }

 function geosisSubmitBudgetAction(actionUrl) {
     var form = document.getElementById('geosis_budget_action_form');
     if (form) {
         form.setAttribute('action', actionUrl);
         form.submit();
     }
 }

section.script:
document.addEventListener('DOMContentLoaded', function() {
    var map = L.map('import_map_picker').setView([-0.1807, -78.4678], 12);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; OpenStreetMap'
    }).addTo(map);

    var marker = L.marker([-0.1807, -78.4678], {
        draggable: true
    }).addTo(map);

    function updateImportFields(lat, lng) {
        document.getElementById('import_lat').value = lat.toFixed(7);
        document.getElementById('import_lng').value = lng.toFixed(7);
        fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`)
            .then(response => response.json())
            .then(data => {
                if (data.address) {
                    var city = data.address.city || data.address.town || data.address.village || data.address.county || '';
                    if (city) document.getElementById('import_location').value = city;
                }
            });
    }

    marker.on('dragend', function() {
        var pos = marker.getLatLng();
        updateImportFields(pos.lat, pos.lng);
    });

    map.on('click', function(e) {
        marker.setLatLng(e.latlng);
        updateImportFields(e.latlng.lat, e.latlng.lng);
    });

    document.getElementById('btn_detect_import').addEventListener('click', function() {
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(function(position) {
                var lat = position.coords.latitude;
                var lng = position.coords.longitude;
                map.setView([lat, lng], 16);
                marker.setLatLng([lat, lng]);
                updateImportFields(lat, lng);
            });
        }
    });

    document.getElementById('btn_search_import').addEventListener('click', function() {
        var query = document.getElementById('import_location').value;
        if (query) {
            fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}`)
                .then(response => response.json())
                .then(data => {
                    if (data.length > 0) {
                        var lat = parseFloat(data[0].lat);
                        var lon = parseFloat(data[0].lon);
                        map.setView([lat, lon], 14);
                        marker.setLatLng([lat, lon]);
                        updateImportFields(lat, lon);
                    }
                });
        }
    });

    // AUTO-DETECCIÓN AL CARGAR (Solo si el campo está vacío)
    function detectImportLocationByIP() {
        var currentLoc = document.getElementById('import_location').value;
        if (!currentLoc) { // Solo si no hay nada escrito
            fetch('https://ipapi.co/json/')
                .then(response => response.json())
                .then(data => {
                    if (data.latitude && data.longitude) {
                        var lat = data.latitude;
                        var lng = data.longitude;
                        map.setView([lat, lng], 14);
                        marker.setLatLng([lat, lng]);
                        updateImportFields(lat, lng);
                    }
                });
        }
    }

    // Solo auto-detectar si el campo de ubicación está vacío
    var initialLocation = document.getElementById('import_location').value;
    if (!initialLocation) {
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(function(position) {
                var lat = position.coords.latitude;
                var lng = position.coords.longitude;
                map.setView([lat, lng], 16);
                marker.setLatLng([lat, lng]);
                updateImportFields(lat, lng);
            }, function(error) {
                console.log("GPS no disponible, usando IP...");
                detectImportLocationByIP();
            });
        } else {
            detectImportLocationByIP();
        }
    }
});

