t.script:
function geosisFilterResources() {
    const categorySelect = document.getElementById('geosis-rubro-category');
    const resourceSelect = document.getElementById('geosis-rubro-resource');
    if (!categorySelect || !resourceSelect) {
        return;
    }
    const category = categorySelect.value;
    let firstVisible = null;
    Array.from(resourceSelect.options).forEach((option) => {
        const visible = option.dataset.category === category;
        option.hidden = !visible;
        if (visible && !firstVisible) {
            firstVisible = option;
        }
    });
    if (firstVisible) {
        resourceSelect.value = firstVisible.value;
    }
    geosisSyncResourceForm();
}

function geosisSyncResourceForm() {
    const resourceSelect = document.getElementById('geosis-rubro-resource');
    const categorySelect = document.getElementById('geosis-rubro-category');
    const rateInput = document.getElementById('geosis-rubro-rate');
    const uomInput = document.getElementById('geosis-rubro-uom');
    if (!resourceSelect) {
        return;
    }
    const selected = resourceSelect.options[resourceSelect.selectedIndex];
    if (!selected) {
        return;
    }
    if (categorySelect && selected.dataset.category) {
        categorySelect.value = selected.dataset.category;
    }
    if (rateInput) {
        rateInput.value = selected.dataset.price || '0';
    }
    if (uomInput) {
        uomInput.value = selected.dataset.uom || '';
    }
    geosisComputeResourceCost();
}

function geosisComputeResourceCost() {
    const quantity = parseFloat(document.getElementById('geosis-rubro-quantity')?.value || '0');
    const rate = parseFloat(document.getElementById('geosis-rubro-rate')?.value || '0');
    const performance = parseFloat(document.getElementById('geosis-rubro-performance')?.value || '0');
    const output = document.getElementById('geosis-rubro-estimated-cost');
    if (!output) {
        return;
    }
    output.textContent = '$' + (quantity * rate * performance).toFixed(2);
}

function geosisToggleEditLine(lineId) {
    const el = document.getElementById('edit-line-' + lineId);
    if (el) {
        el.classList.toggle('d-none');
    }
}

geosisFilterResources();

form.script:
// 
document.addEventListener('DOMContentLoaded', function() {
    var mapContainer = document.getElementById('geosis_leaflet_map');
    if (!mapContainer) return;

    var input = document.getElementById('resource_location_input');
    var btnGeolocate = document.getElementById('btn_geolocate');

    // Inicializar el mapa centrado en Ecuador
    var defaultLat = -1.8312;
    var defaultLon = -78.1834;
    var map = L.map('geosis_leaflet_map').setView([defaultLat, defaultLon], 7);

    // Capa de mapas OpenStreetMap standard
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        maxZoom: 18,
        attribution: '© OpenStreetMap contributors'
    }).addTo(map);

    // Marcador inicial
    var marker = L.marker([defaultLat, defaultLon], { draggable: true }).addTo(map);

    // Función para buscar la ciudad/provincia usando Nominatim (Reverse Geocoding)
    function updateLocationFromCoords(lat, lon) {
        marker.setLatLng([lat, lon]);
        map.panTo([lat, lon]);

        var url = 'https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=' + lat + '&lon=' + lon;
        fetch(url, {
            headers: {
                'Accept-Language': 'es'
            }
        })
        .then(response => response.json())
        .then(data => {
            if (data && data.address) {
                var address = data.address;
                var city = address.city || address.town || address.village || address.city_district || address.county || address.state || '';

                if (city) {
                    // Eliminar palabras genéricas como "Cantón" si Nominatim las devuelve
                    city = city.replace(/cantón/gi, '').trim();
                    input.value = city;
                } else {
                    input.value = 'Cuenca';
                }
            }
        })
        .catch(err => {
            console.error("Error geocodificando: ", err);
        });
    }

    // Evento al arrastrar el marcador
    marker.on('dragend', function(e) {
        var position = marker.getLatLng();
        updateLocationFromCoords(position.lat, position.lng);
    });

    // Evento al hacer clic en el mapa
    map.on('click', function(e) {
        updateLocationFromCoords(e.latlng.lat, e.latlng.lng);
    });

    // Evento para autodetectar coordenadas (Geolocalización del navegador)
    btnGeolocate.addEventListener('click', function() {
        if (navigator.geolocation) {
            btnGeolocate.disabled = true;
            btnGeolocate.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Detectando...';

            navigator.geolocation.getCurrentPosition(
                function(position) {
                    var lat = position.coords.latitude;
                    var lon = position.coords.longitude;
                    map.setView([lat, lon], 14);
                    updateLocationFromCoords(lat, lon);

                    btnGeolocate.disabled = false;
                    btnGeolocate.innerHTML = '<i class="fa fa-location-arrow"></i> Detectar Mi Ubicación';
                },
                function(error) {
                    alert("No se pudo detectar tu ubicación automáticamente. Selecciona un punto en el mapa manualmente.");
                    btnGeolocate.disabled = false;
                    btnGeolocate.innerHTML = '<i class="fa fa-location-arrow"></i> Detectar Mi Ubicación';
                },
                { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
            );
        } else {
            alert("Tu navegador no soporta la geolocalización. Selecciona un punto en el mapa.");
        }
    });

    // Si el campo ya tiene una ubicación por defecto (ej. al editar)
    var existingLoc = input.value.trim();
    if (existingLoc && existingLoc.toLowerCase() !== 'global' && existingLoc.toLowerCase() !== '') {
        var searchUrl = 'https://nominatim.openstreetmap.org/search?format=json&q=' + encodeURIComponent(existingLoc) + '&limit=1';
        fetch(searchUrl)
        .then(response => response.json())
        .then(results => {
            if (results && results.length > 0) {
                var lat = parseFloat(results[0].lat);
                var lon = parseFloat(results[0].lon);
                map.setView([lat, lon], 12);
                marker.setLatLng([lat, lon]);
            }
        })
        .catch(err => console.log(err));
    }
});
//

