    if (el) {
        el.classList.toggle('d-none');
    }
}

document.addEventListener('DOMContentLoaded', function() {
    // 1. Definición de Capas del Mapa
    var layers = {
        streets: L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
            attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>'
        }),
        satellite: L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
            attribution: 'Tiles &copy; Esri &mdash; Source: Esri, i-cubed, USDA, USGS, AEX, GeoEye, Getmapping, Aerogrid, IGN, IGP, UPR-EGP, and the GIS User Community'
        }),
        terrain: L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/{z}/{y}/{x}', {
            attribution: 'Tiles &copy; Esri &mdash; Esri, DeLorme, NAVTEQ, TomTom, Intermap, iPC, USGS, FAO, NPS, NRCAN, GeoBase, Kadaster NL, Ordnance Survey, Esri Japan, METI, Esri China (Hong Kong), and the GIS User Community'
        }),
        dark: L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
            attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>'
        })
    };

    // 2. Inicialización del Mapa
    var map = L.map('geosis-main-map', {
        center: [-1.8312, -78.1834],
        zoom: 7,
        layers: [layers.streets]
    });

    // 3. Datos de Odoo
    var projectsData = [


                {
                    id: ,
                    name: "",
                    code: "",
                    location: "",
                    partner: "",
                    state: "",
                    state_label: "",
                    budget_count: ,
                    budget_amount: "",
                    currency: "",
                    start_date: "",
                    lat: ,
                    lng: 
                },


    ];

    var markersMap = {};
    var group = new L.featureGroup();

    // Función para obtener color de estado
    function getStateColor(state) {
        switch(state) {
            case 'planning': return '#536d83';
            case 'active': return '#7a9282';
            case 'completed': return '#78aeb1';
            default: return '#8a8178';
        }
    }

    // 4. Renderizado de Marcadores Personalizados
    projectsData.forEach(function(p) {
        var markerColor = getStateColor(p.state);

        var customHtml = `
            <div class="geosis-marker-pin" style="--marker-color: ${markerColor}">
                <i class="fa fa-building-o"></i>
            </div>
            <div class="geosis-marker-pulse" style="--marker-color: ${markerColor}"></div>
        `;

        var customIcon = L.divIcon({
            className: 'geosis-custom-marker',
            html: customHtml,
            iconSize: [30, 42],
            iconAnchor: [15, 42],
            popupAnchor: [0, -40]
        });

        var popupHtml = `
            <div class="geosis-popup-card">
                <div class="geosis-popup-header">
                    <span>${p.code} &bull; ${p.state_label}</span>
                    <h4>${p.name}</h4>
                </div>
                <div class="geosis-popup-body">
                    <div class="geosis-popup-info-row">
                        <i class="fa fa-map-marker"></i>
                        <span>${p.location || 'Sin ubicación'}</span>
                    </div>
                    <div class="geosis-popup-info-row">
                        <i class="fa fa-user"></i>
                        <span>Socio: <strong>${p.partner}</strong></span>
                    </div>
                    <div class="geosis-popup-info-row">
                        <i class="fa fa-calculator"></i>
                        <span>${p.budget_count} Presupuesto(s) &bull; <strong>${p.currency} ${p.budget_amount}</strong></span>
                    </div>
                </div>
                <div class="geosis-popup-footer">
                    <a href="/my/rubros?location=${encodeURIComponent(p.location)}" class="btn btn-primary btn-sm w-100 py-1" style="font-size: 0.65rem;">
                        <i class="fa fa-database me-1"></i> Base de Datos
                    </a>
                    <a href="/my/projects/${p.id}" class="btn btn-outline-primary btn-sm w-100 py-1" style="font-size: 0.65rem;">
                        <i class="fa fa-building me-1"></i> Ver Proyecto
                    </a>
                </div>
            </div>
        `;

        var marker = L.marker([p.lat, p.lng], {icon: customIcon})
            .addTo(map)
            .bindPopup(popupHtml);

        markersMap[p.id] = marker;
        group.addLayer(marker);
    });

    if (group.getLayers().length > 0) {
        map.fitBounds(group.getBounds().pad(0.1));
    }

    // 5. Interactividad del Selector de Capas
    document.querySelectorAll('.geosis-map-style-btn').forEach(function(btn) {
        btn.addEventListener('click', function() {
            document.querySelectorAll('.geosis-map-style-btn').forEach(function(b) {
                b.classList.remove('is-active');
            });
            btn.classList.add('is-active');

            var layerType = btn.getAttribute('data-layer-type');
            // Remover capas anteriores
            Object.keys(layers).forEach(function(k) {
                map.removeLayer(layers[k]);
            });
            // Añadir capa seleccionada
            map.addLayer(layers[layerType]);
        });
    });

    // 6. Sincronización entre Lista y Mapa al Hacer Clic en Sidebar Card
    document.querySelectorAll('.project-sidebar-card').forEach(function(card) {
        card.addEventListener('click', function(e) {
            e.preventDefault();

            document.querySelectorAll('.project-sidebar-card').forEach(function(c) {
                c.classList.remove('is-active');
            });
            card.classList.add('is-active');

            var lat = parseFloat(card.getAttribute('data-lat'));
            var lng = parseFloat(card.getAttribute('data-lng'));
            var pId = card.getAttribute('data-project-id');

            map.flyTo([lat, lng], 13, {
                animate: true,
                duration: 1.5
            });

            if (markersMap[pId]) {
                setTimeout(function() {
                    markersMap[pId].openPopup();
                }, 1500);
            }
        });
    });

    // 7. Filtrado Dinámico de Tarjetas y Marcadores (Buscador y Selector de Estado)
    var searchInput = document.getElementById('map-search');
    var statusFilter = document.getElementById('map-status-filter');

    function filterData() {
        var query = searchInput.value.toLowerCase().trim();
        var selectedStatus = statusFilter.value;
        var visibleCount = 0;
        var totalBudget = 0;

        projectsData.forEach(function(p) {
            var matchesSearch = p.name.toLowerCase().includes(query) || p.code.toLowerCase().includes(query) || p.location.toLowerCase().includes(query);
            var matchesStatus = selectedStatus === 'all' || p.state === selectedStatus;
            var show = matchesSearch && matchesStatus;

            var card = document.querySelector('.project-sidebar-card[data-project-id="' + p.id + '"]');
            var marker = markersMap[p.id];

            if (show) {
                if (card) card.style.display = 'block';
                if (marker) {
                    if (!map.hasLayer(marker)) map.addLayer(marker);
                }
                visibleCount++;
                var amount = parseFloat(p.budget_amount.replace(/,/g, ''));
                if (!isNaN(amount)) {
                    totalBudget += amount;
                }
            } else {
                if (card) card.style.display = 'none';
                if (marker) {
                    if (map.hasLayer(marker)) map.removeLayer(marker);
                }
            }
        });

        document.getElementById('total-projects-badge').innerText = visibleCount;
        var formattedBudget = totalBudget.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        var totalBudgetEl = document.getElementById('total-budget-sum-badge');
        if (totalBudgetEl) {
            totalBudgetEl.innerText = '$ ' + formattedBudget;
        }
    }

    // Inicializar el total al cargar
    filterData();

    searchInput.addEventListener('input', filterData);
    statusFilter.addEventListener('change', filterData);
});

document.addEventListener("DOMContentLoaded", function() {
    var canvas = document.getElementById('fiscalizador_signature_canvas');
    if (!canvas) return;
    var ctx = canvas.getContext('2d');
    ctx.lineWidth = 3;
    ctx.strokeStyle = "#000000";
    ctx.lineCap = "round";

    canvas.width = canvas.offsetWidth;
    canvas.height = canvas.offsetHeight;

    var drawing = false;
    var lastPos = { x:0, y:0 };

    function getMousePos(canvasDom, touchOrMouseEvent) {
        var rect = canvasDom.getBoundingClientRect();
        var clientX = touchOrMouseEvent.touches ? touchOrMouseEvent.touches[0].clientX : touchOrMouseEvent.clientX;
        var clientY = touchOrMouseEvent.touches ? touchOrMouseEvent.touches[0].clientY : touchOrMouseEvent.clientY;
        return {
            x: clientX - rect.left,
            y: clientY - rect.top
        };
    }

    function startDrawing(e) {
        drawing = true;
        lastPos = getMousePos(canvas, e);
        ctx.beginPath();
        ctx.moveTo(lastPos.x, lastPos.y);
    }

    function draw(e) {
        if (!drawing) return;
        e.preventDefault();
        var pos = getMousePos(canvas, e);
        ctx.lineTo(pos.x, pos.y);
        ctx.stroke();
    }

    function stopDrawing() {
        drawing = false;
    }

    canvas.addEventListener("mousedown", startDrawing);
    canvas.addEventListener("mousemove", draw);
    canvas.addEventListener("mouseup", stopDrawing);
    canvas.addEventListener("mouseout", stopDrawing);

    canvas.addEventListener("touchstart", startDrawing);
    canvas.addEventListener("touchmove", draw);
    canvas.addEventListener("touchend", stopDrawing);

    document.getElementById('btn_clear_web_signature').addEventListener("click", function() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
    });

    document.getElementById('form_fiscalizar_bitacora').addEventListener("submit", function(e) {
        var dataURL = canvas.toDataURL("image/png");
        document.getElementById('signature_inspector_base64').value = dataURL;
    });
});
